/// `reminders.updateReminder` → updates `TaskItem` items through the inbox.
@available(iOS 27.0, macOS 27.0, *)
@AppIntent(schema: .reminders.updateReminder)
struct TaskItemUpdateReminderIntent {
  var target: TaskItemEntity
  var title: String?
  var note: AttributedString?
  var tags: Set<String>?
  var urls: [URL]?
  var dueDate: DateComponents?
  var recurrence: Calendar.RecurrenceRule?
  var isCompleted: Bool?
  var isFlagged: Bool?
  var list: RemindersListEntity?
  var locationTrigger: RemindersLocationTriggerEntity?

  @MainActor
  func perform() async throws -> some ReturnsValue<TaskItemEntity> & ProvidesDialog {
    var fields: [String: Any] = [:]
    var cleared: [String] = []
    if title != nil { fields["title"] = AssistantValues.encode(title) }
    switch $dueDate.valueState {
    case .unset: break
    case .set(let value?): fields["due"] = AssistantValues.encode(value)
    case .set(nil): cleared.append("due")
    @unknown default: break
    }
    if isCompleted != nil { fields["done"] = AssistantValues.encode(isCompleted) }
    let before = AssistantUndo.records("TaskItem", ids: [target.id]).first
    AssistantInbox.update("TaskItem", id: target.id, fields: fields, cleared: cleared)
    await AssistantBackground.shared.applyInbox()
    AssistantUndo.register(undoManager, "Update Reminder", AssistantUndo.update("TaskItem", id: target.id, before: before, fields: fields, cleared: cleared)) { Task { await AssistantBackground.shared.applyInbox() } }
    let updated = target
    if let value = fields["title"] {
      updated.title = AssistantValues.string(value) ?? ""
    }
    if let value = fields["due"] {
      updated.dueDate = AssistantValues.dateComponents(value)
    } else if cleared.contains("due") {
      updated.dueDate = nil
    }
    if let value = fields["done"] {
      updated.isCompleted = AssistantValues.bool(value) ?? false
    }
    return .result(value: updated, dialog: IntentDialog(stringLiteral: "Updated \(updated.title)."))
  }
}

